import{_ as t,c as e,o as r,ae as o}from"./chunks/framework.DNEoaTf_.js";const b=JSON.parse('{"title":"プライバシーポリシー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/privacy.md","filePath":"ja/privacy.md"}'),l={name:"ja/privacy.md"};function i(h,a,s,n,u,d){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p>最終更新日: 2024年11月24日</p><h2 id="データ収集について" tabindex="-1">データ収集について <a class="header-anchor" href="#データ収集について" aria-label="Permalink to &quot;データ収集について&quot;">​</a></h2><p>YouTube Watch Thumbnails（以下「本拡張機能」）は、ユーザーのプライバシーを最優先に考えて設計されています。</p><h3 id="収集・保存するデータ" tabindex="-1">収集・保存するデータ <a class="header-anchor" href="#収集・保存するデータ" aria-label="Permalink to &quot;収集・保存するデータ&quot;">​</a></h3><p>本拡張機能は、以下のデータをブラウザのローカルストレージに保存します：</p><ul><li><strong>動画ID</strong>: サムネイルを表示した YouTube 動画の ID（文字列）</li><li><strong>拡張機能の設定</strong>: ユーザーが行った設定（文字列）</li></ul><h3 id="データの保存場所" tabindex="-1">データの保存場所 <a class="header-anchor" href="#データの保存場所" aria-label="Permalink to &quot;データの保存場所&quot;">​</a></h3><p>すべてのデータは、ブラウザのローカルストレージ（<code>chrome.storage.local</code> または <code>browser.storage.local</code>）に保存されます。</p><ul><li><strong>外部サーバーへの送信</strong>: 一切行いません</li><li><strong>保存場所</strong>: ユーザーのデバイス内のみ</li><li><strong>第三者アクセス</strong>: 不可能</li></ul><h3 id="収集しないデータ" tabindex="-1">収集しないデータ <a class="header-anchor" href="#収集しないデータ" aria-label="Permalink to &quot;収集しないデータ&quot;">​</a></h3><p>本拡張機能は、以下のデータを収集・保存しません：</p><ul><li>ログイン情報やパスワード</li><li>YouTube 以外のブラウジング履歴</li><li>個人を特定できる情報（氏名、メールアドレスなど）</li><li>使用状況の統計やアナリティクス</li></ul><h2 id="データの使用目的" tabindex="-1">データの使用目的 <a class="header-anchor" href="#データの使用目的" aria-label="Permalink to &quot;データの使用目的&quot;">​</a></h2><p>保存したデータは、以下の目的でのみ使用されます：</p><ol><li><strong>動画ID</strong>: 最近表示したサムネイルの履歴管理</li><li><strong>設定</strong>: ユーザーの設定を保持し、次回使用時に復元</li></ol><p>YouTube の公開 API からサムネイル情報を取得し、ブラウザ上に表示します。</p><h2 id="データの共有" tabindex="-1">データの共有 <a class="header-anchor" href="#データの共有" aria-label="Permalink to &quot;データの共有&quot;">​</a></h2><p><strong>本拡張機能は、保存したデータを第三者と共有することは一切ありません。</strong></p><p>すべてのデータはローカルに保存され、外部への送信は行われません。</p><h2 id="データの削除" tabindex="-1">データの削除 <a class="header-anchor" href="#データの削除" aria-label="Permalink to &quot;データの削除&quot;">​</a></h2><p>ユーザーは、いつでも以下の方法でデータを削除できます：</p><h3 id="ブラウザのストレージをクリア" tabindex="-1">ブラウザのストレージをクリア <a class="header-anchor" href="#ブラウザのストレージをクリア" aria-label="Permalink to &quot;ブラウザのストレージをクリア&quot;">​</a></h3><p>ブラウザの設定から、拡張機能のストレージデータを削除できます。</p><h3 id="拡張機能をアンインストール" tabindex="-1">拡張機能をアンインストール <a class="header-anchor" href="#拡張機能をアンインストール" aria-label="Permalink to &quot;拡張機能をアンインストール&quot;">​</a></h3><p>拡張機能をアンインストールすると、保存されているすべてのデータが自動的に削除されます。</p><h2 id="権限について" tabindex="-1">権限について <a class="header-anchor" href="#権限について" aria-label="Permalink to &quot;権限について&quot;">​</a></h2><p>本拡張機能が要求する権限とその理由：</p><table tabindex="0"><thead><tr><th>権限</th><th>理由</th></tr></thead><tbody><tr><td><code>tabs</code></td><td>YouTube のタブ情報を取得し、動画情報にアクセスするため</td></tr><tr><td><code>storage</code></td><td>拡張機能の設定を保存するため</td></tr></tbody></table><h2 id="セキュリティ" tabindex="-1">セキュリティ <a class="header-anchor" href="#セキュリティ" aria-label="Permalink to &quot;セキュリティ&quot;">​</a></h2><p>本拡張機能は、以下のセキュリティ対策を実施しています：</p><ul><li>すべての通信は HTTPS（暗号化された通信）のみを使用</li><li>外部への通信は YouTube の公開 API のみに制限</li><li>オープンソースとして公開し、コードの透明性を確保</li></ul><h2 id="子供のプライバシー" tabindex="-1">子供のプライバシー <a class="header-anchor" href="#子供のプライバシー" aria-label="Permalink to &quot;子供のプライバシー&quot;">​</a></h2><p>本拡張機能は、13歳未満の子供を対象としていません。また、年齢に関わらず個人データを収集することはありません。</p><h2 id="変更の通知" tabindex="-1">変更の通知 <a class="header-anchor" href="#変更の通知" aria-label="Permalink to &quot;変更の通知&quot;">​</a></h2><p>このプライバシーポリシーを変更する場合、拡張機能のアップデート時に通知します。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーに関するご質問は、以下までお問い合わせください：</p><ul><li>GitHub Issues: <a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">https://github.com/mosunset/youtube_watch_thumbnails/issues</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">透明性の確保</p><p>本拡張機能は、<a href="https://github.com/mosunset/youtube_watch_thumbnails" target="_blank" rel="noreferrer">GitHub</a> でオープンソースとして公開されています。コードを自由に確認できます。</p></div>',41)])])}const p=t(l,[["render",i]]);export{b as __pageData,p as default};
